-- migration_022_teams.sql
-- 575 teams (TM + TEAM prefixes) + team_writers + title backfill

-- Create teams table
CREATE TABLE IF NOT EXISTS teams (
  team_id VARCHAR(10) PRIMARY KEY,
  composer_prefix VARCHAR(10) NOT NULL,
  composer_full_id VARCHAR(10) NOT NULL,
  pub_splits TEXT,
  writer_splits TEXT,
  pub_detail TEXT,
  writer_detail TEXT,
  status VARCHAR(50),
  has_cowriters BOOLEAN DEFAULT false,
  registered_date DATE,
  is_jup BOOLEAN NOT NULL DEFAULT false
);

-- Create team_writers join table
CREATE TABLE IF NOT EXISTS team_writers (
  id SERIAL PRIMARY KEY,
  team_id VARCHAR(10) NOT NULL REFERENCES teams(team_id) ON DELETE CASCADE,
  writer_name TEXT NOT NULL,
  pro VARCHAR(20),
  split_pct NUMERIC(5,2),
  is_jup BOOLEAN NOT NULL DEFAULT false
);

