;

-- Add team_id FK to titles (idempotent)
ALTER TABLE titles ADD COLUMN IF NOT EXISTS team_id VARCHAR(10) REFERENCES teams(team_id);

-- Backfill team_id on titles by matching composer_full_id prefix against sku_root
UPDATE titles t
SET team_id = tm.team_id
FROM teams tm
WHERE t.sku_root LIKE tm.composer_full_id || '%'
  AND t.team_id IS NULL;